mapper.select:
SELECT layer.tenant_id AS tenantId, layer.dept_id AS deptId, dept.dept_name AS deptName, layer.product_id AS productId, prod.product_code AS productCode, COALESCE(prod.product_name, '') AS productName, layer.stock_quantity AS closingQuantity, layer.avg_unit_cost AS avgUnitCost, layer.stock_amount AS closingAmount, COALESCE(rng.inbound_amount, 0) AS inboundAmount, COALESCE(rng.sale_cost, 0) AS saleCost, COALESCE(rng.adjustment_amount, 0) AS adjustmentAmount, COALESCE(rev.sale_revenue, 0) AS saleRevenue, (COALESCE(rev.sale_revenue, 0) - COALESCE(rng.sale_cost, 0)) AS grossProfit FROM fin_stock_cost_layer layer LEFT JOIN fin_product prod ON prod.product_id = layer.product_id AND prod.del_flag = '0' LEFT JOIN sys_dept dept ON dept.dept_id = layer.dept_id LEFT JOIN ( SELECT tenant_id, dept_id, product_id, COALESCE(SUM(CASE WHEN cost_change_type = 'COST_IN' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN cost_change_type = 'COST_REVERSE_OUT' THEN amount ELSE 0 END), 0) AS inbound_amount, COALESCE(SUM(CASE WHEN cost_change_type = 'COST_OUT' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN cost_change_type = 'COST_REVERSE_IN' THEN amount ELSE 0 END), 0) AS sale_cost , COALESCE(SUM(CASE WHEN cost_change_type = 'COST_ADJUST' THEN amount ELSE 0 END), 0) AS adjustment_amount FROM fin_stock_cost_ledger WHERE AND create_time >= #{query.startDate} AND create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY) GROUP BY tenant_id, dept_id, product_id ) rng ON rng.tenant_id = layer.tenant_id AND rng.dept_id = layer.dept_id AND rng.product_id = layer.product_id LEFT JOIN ( SELECT dept_id, product_id, SUM(sale_amount) AS sale_revenue FROM fin_sale_record WHERE AND sale_date >= #{query.startDate} AND sale_date < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY) GROUP BY dept_id, product_id ) rev ON rev.dept_id = layer.dept_id AND rev.product_id = layer.product_id WHERE layer.tenant_id = #{tenantId}
AND layer.dept_id IN
#{deptId}
ORDER BY layer.tenant_id, layer.dept_id, layer.product_id

SELECT EXISTS(
    SELECT 1 FROM fin_stock_cost_layer
    WHERE tenant_id = #{tenantId}

          AND dept_id IN

              #{deptId}


    LIMIT 1
)
